ALTER TABLE "copy_execution_accounts" ADD COLUMN "master_policy_fingerprint" text;--> statement-breakpoint
ALTER TABLE "copy_execution_accounts" ADD COLUMN "master_signer_quorum_id" text;--> statement-breakpoint
